import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { beforeAll, describe, expect, it } from "vitest";
import { makeTempDir } from "../helpers/tmp.js";

// covers: S13.cli-usage-drift
// Spec §13: the usage text in the docs equals what the built CLI prints. docs/cli-usage.md is generated by
// scripts/cli-usage.mjs, so a command that changed without regenerating the file fails here and the failure names the verb.
const ROOT = fileURLToPath(new URL("../../", import.meta.url));
const SCRIPT = join(ROOT, "scripts/cli-usage.mjs");

interface Block {
  path: string;
  help: string;
}
const usage = (await import(SCRIPT)) as {
  discoverLeaves: (runHelp: (prefix: string[]) => string) => Block[];
  builtHelpRunner: (cli: string, home: string, cwd: string) => (prefix: string[]) => string;
  compareUsage: (expected: Block[], text: string) => string[];
};
const doc = (): string => readFileSync(join(ROOT, "docs/cli-usage.md"), "utf8");
const check = (args: string[]) =>
  spawnSync(process.execPath, [SCRIPT, "--check", ...args], {
    cwd: ROOT,
    encoding: "utf8",
    env: { PATH: process.env.PATH ?? "" },
  });

describe("docs/cli-usage.md", () => {
  let blocks: Block[] = [];

  beforeAll(() => {
    const scratch = makeTempDir("omf-usage-");
    blocks = usage.discoverLeaves(usage.builtHelpRunner(join(ROOT, "dist/cli/main.js"), scratch, scratch));
  }, 60_000);

  it("equals the built CLI's --help for every leaf command", () => {
    expect(usage.compareUsage(blocks, doc())).toEqual([]);
  });

  it("has a block for each verb of the verification line", () => {
    const paths = blocks.map((block) => block.path);
    for (const verb of ["decide lint", "seal", "run", "report"]) expect(paths).toContain(verb);
  });

  it("fails on a one-character edit and names the verb", () => {
    const edited = doc().replace("## omf seal\n\n```text\nUsage:", "## omf seal\n\n```text\nUsagf:");
    expect(edited).not.toBe(doc());
    expect(usage.compareUsage(blocks, edited)).toEqual(["omf seal: the block differs from --help"]);
  });

  it("fails on a command that has no block", () => {
    const without = doc().replace(/## omf report\n\n```text\n[\s\S]*?\n```\n/, "");
    expect(without).not.toBe(doc());
    expect(usage.compareUsage(blocks, without)).toEqual(["omf report: no block in docs/cli-usage.md"]);
  });

  it("--check exits 0 on the checked-in file and 1, naming the verb, on an edited copy", () => {
    expect(check([]).status).toBe(0);
    const copy = join(makeTempDir("omf-usage-"), "cli-usage.md");
    writeFileSync(copy, doc().replace("## omf run\n\n```text\nUsage:", "## omf run\n\n```text\nUsagf:"));
    const bad = check(["--file", copy]);
    expect(bad.status).toBe(1);
    expect(bad.stderr).toContain("omf run: the block differs from --help");
  }, 60_000);
});
